import { Registry, Gauge } from 'prom-client';
import { KafkaConfigProvider } from './config/kafka-config-provider';
import { KafkaEventProducer } from './producer/producer';
import { FraudEventConsumer } from './consumer/consumer';
import { MetricsManager } from './telemetry/metrics-manager';
import { Transaction } from '../../../core/domain_models/definitions/transaction.interface';

/**
 * KafkaMessagingClient
 * 
 * Acts as the primary facade for the messaging subsystem. 
 * Orchestrates producers, consumers, and lifecycle management.
 */
export class KafkaMessagingClient {
  private static instance: KafkaMessagingClient;

  private readonly configProvider: KafkaConfigProvider;
  private readonly metrics: MetricsManager;
  private readonly producer: KafkaEventProducer;
  private readonly consumers: FraudEventConsumer[] = [];

  private readonly statusGauge: Gauge<string>;
  private isRunning: boolean = false;

  private constructor(registry: Registry) {
    const env = process.env;
    this.metrics = MetricsManager.initialize(registry);
    this.configProvider = KafkaConfigProvider.initialize(env, registry);
    this.producer = KafkaEventProducer.initialize(this.configProvider, this.metrics);

    this.statusGauge = new Gauge({
      name: 'messaging_client_status',
      help: '1 if messaging client is running, 0 otherwise',
      registers: [registry],
      labelNames: ['component'],
    });
  }

  public static getInstance(registry: Registry): KafkaMessagingClient {
    if (!KafkaMessagingClient.instance) {
      KafkaMessagingClient.instance = new KafkaMessagingClient(registry);
    }
    return KafkaMessagingClient.instance;
  }

  /**
   * Bootstraps the messaging subsystem.
   */
  public async start(): Promise<void> {
    if (this.isRunning) return;

    try {
      await this.producer.connect();
      this.statusGauge.labels('producer').set(1);

      for (const consumer of this.consumers) {
        await consumer.start();
        this.statusGauge.labels('consumer').set(1);
      }

      this.isRunning = true;
      this.producer.registerShutdownHandlers();

      // Ensure graceful shutdown is handled
      process.on('SIGTERM', () => this.shutdown());
      process.on('SIGINT', () => this.shutdown());
    } catch (error) {
      this.statusGauge.labels('producer').set(0);
      throw new Error(`Failed to initialize KafkaMessagingClient: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Publishes a transaction event to the specified topic.
   */
  public async publish<T extends Transaction>(topic: string, event: T): Promise<void> {
    if (!this.isRunning) {
      throw new Error('Messaging client is not running');
    }
    await this.producer.produce(topic, event);
  }

  /**
   * Registers a new consumer instance.
   */
  public registerConsumer(consumer: FraudEventConsumer): void {
    this.consumers.push(consumer);
  }

  /**
   * Performs a graceful shutdown of all components.
   */
  public async shutdown(): Promise<void> {
    if (!this.isRunning) return;

    try {
      await this.producer.gracefulShutdown();
      for (const consumer of this.consumers) {
        await consumer.shutdown();
      }
      this.statusGauge.labels('producer').set(0);
      this.statusGauge.labels('consumer').set(0);
      this.isRunning = false;
    } catch (error) {
      console.error('Error during messaging client shutdown:', error);
    }
  }
}

import { Kafka, Consumer, EachBatchPayload } from 'kafkajs';
import { KafkaConfig, KafkaConfigProvider } from '../config/kafka-config-provider';
import { MetricsManager } from '../telemetry/metrics-manager';
import { EventEnvelopeFactory, MessageEnvelope } from '../../../../core/domain_models/messaging/event-envelope.messaging';
import { TransactionSchema } from '../contracts/contracts';
import { ProjectionStore } from '../../../../store/projection_store/projection-store';
import { Transaction } from '../../../../core/domain_models/definitions/transaction.interface';

/**
 * Production-grade Kafka Consumer for the Fraud Detection Engine.
 * Handles event ingestion, cryptographic verification, DLQ routing, and state projection.
 */
export class FraudEventConsumer {
  private readonly consumer: Consumer;
  private readonly kafka: Kafka;
  private readonly config: KafkaConfig;
  private readonly metrics: MetricsManager;
  private readonly projectionStore: ProjectionStore;

  constructor(
    private readonly topic: string,
    private readonly dlqTopic: string = 'fraud-dlq'
  ) {
    this.config = KafkaConfigProvider.getInstance().getConfig();
    this.metrics = MetricsManager.getInstance();
    this.projectionStore = ProjectionStore.getInstance();

    this.kafka = new Kafka({
      clientId: this.config.clientId,
      brokers: this.config.brokers,
      sasl: this.config.sasl,
      ssl: this.config.ssl,
    });

    this.consumer = this.kafka.consumer({
      groupId: this.config.groupId,
      sessionTimeout: this.config.consumer.sessionTimeout,
      heartbeatInterval: this.config.consumer.heartbeatInterval,
    });
  }

  public async start(): Promise<void> {
    await this.consumer.connect();
    await this.consumer.subscribe({ topic: this.topic, fromBeginning: false });

    this.consumer.on('consumer.group_join', () => {
      this.metrics.recordRebalance({ environment: process.env.NODE_ENV || 'production', stream: this.topic });
    });

    await this.consumer.run({
      eachBatchAutoResolve: false,
      eachBatch: async (payload: EachBatchPayload) => {
        const { batch, resolveOffset, heartbeat } = payload;
        const environment = process.env.NODE_ENV || 'production';

        for (const message of batch.messages) {
          const startTime = process.hrtime.bigint();

          try {
            if (!message.value) continue;

            const envelope = JSON.parse(message.value.toString()) as MessageEnvelope<Transaction>;

            // 1. Verify Integrity (Cryptographic signature check)
            await EventEnvelopeFactory.verifyEnvelope(envelope);

            // 2. Validate Contract (Runtime Zod validation)
            const validation = TransactionSchema.safeParse(envelope.payload);
            if (!validation.success) {
              throw new Error(`Schema validation failed: ${JSON.stringify(validation.error)}`);
            }

            // 3. Process Projection (State update via ProjectionStore)
            const tx = validation.data;
            await this.projectionStore.processTransaction(
              tx.userId,
              tx.amount.value,
              tx.transactionId,
              60 // 60s sliding window
            );

            // 4. Success metrics
            this.metrics.recordConsumerLatency({ environment, stream: this.topic }, startTime);
            this.metrics.recordConsumerEventsConsumed({ environment, stream: this.topic });
            resolveOffset(message.offset);

          } catch (err) {
            const reason = err instanceof Error ? err.message : 'Unknown processing error';

            // Route to DLQ (Dead Letter Queue)
            await this.kafka.producer().send({
              topic: this.dlqTopic,
              messages: [{
                key: message.key,
                value: JSON.stringify({
                  originalPayload: message.value?.toString(),
                  error: reason,
                  timestamp: Date.now()
                })
              }]
            });

            this.metrics.recordDlqIngressCount({ environment, stream: this.topic }, reason);

            // Still resolve offset to continue processing stream
            resolveOffset(message.offset);
          }

          await heartbeat();
        }
      },
    });
  }

  public async shutdown(): Promise<void> {
    await this.consumer.disconnect();
  }
}

import { z } from 'zod';

/**
 * Zod schema for validated Branded identifiers.
 */
const BrandedString = (brand: string) =>
  z.string().min(1, `${brand} cannot be empty`);

/**
 * Zod schema for MonetaryAmount.
 */
export const MonetaryAmountSchema = z.object({
  value: z.bigint(),
  currency: z.string().length(3, 'Currency must be a 3-letter ISO code'),
});

/**
 * Zod schema for Telemetry.
 */
export const TelemetrySchema = z.object({
  latitude: z.number(),
  longitude: z.number(),
  deviceFingerprint: z.string().min(1),
  ipAddress: z.string().ip(),
  userAgent: z.string().min(1),
});

/**
 * Base schema for all transaction events.
 */
const TransactionEventBaseSchema = z.object({
  transactionId: BrandedString('TransactionId'),
  userId: BrandedString('UserId'),
  merchantId: BrandedString('MerchantId'),
  amount: MonetaryAmountSchema,
  timestamp: z.bigint(),
  telemetry: TelemetrySchema,
});

/**
 * Schema for TransactionInitiated.
 */
export const TransactionInitiatedSchema = TransactionEventBaseSchema.extend({
  type: z.literal('TransactionInitiated'),
});

/**
 * Schema for TransactionValidated.
 */
export const TransactionValidatedSchema = TransactionEventBaseSchema.extend({
  type: z.literal('TransactionValidated'),
  validatorId: z.string().min(1),
});

/**
 * Schema for TransactionFlagged.
 */
export const TransactionFlaggedSchema = TransactionEventBaseSchema.extend({
  type: z.literal('TransactionFlagged'),
  reason: z.string().min(1),
  riskScore: z.number().min(0).max(1),
});

/**
 * Discriminated union of all transaction event types.
 */
export const TransactionSchema = z.discriminatedUnion('type', [
  TransactionInitiatedSchema,
  TransactionValidatedSchema,
  TransactionFlaggedSchema,
]);

/**
 * Schema for EnvelopeMetadata.
 */
export const EnvelopeMetadataSchema = z.object({
  schemaVersion: z.string().min(1),
  createdAtNs: z.bigint(),
  provenanceTrace: z.string().min(1),
});

/**
 * Generic Schema factory for MessageEnvelope.
 */
export const MessageEnvelopeSchema = <T extends z.ZodTypeAny>(payloadSchema: T) =>
  z.object({
    metadata: EnvelopeMetadataSchema,
    payload: payloadSchema,
    signature: z.string().min(1, 'Signature cannot be empty'),
  });

/**
 * Type-safe inferred types.
 */
export type TransactionInitiatedPayload = z.infer<typeof TransactionInitiatedSchema>;
export type TransactionValidatedPayload = z.infer<typeof TransactionValidatedSchema>;
export type TransactionFlaggedPayload = z.infer<typeof TransactionFlaggedSchema>;
export type TransactionPayload = z.infer<typeof TransactionSchema>;
export type EnvelopeMetadata = z.infer<typeof EnvelopeMetadataSchema>;
export type MessageEnvelope<T> = z.infer<ReturnType<typeof MessageEnvelopeSchema<z.ZodType<T>>>>;

import { Kafka, Producer, ProducerRecord, CompressionTypes } from 'kafkajs';
import { KafkaConfigProvider } from '../config/kafka-config-provider';
import { EventEnvelopeFactory } from '../../domain_models/messaging/event-envelope.messaging';
import { MetricsManager, MetricLabels } from '../telemetry/metrics-manager';
import { Transaction } from '../../domain_models/definitions/transaction.interface';

/**
 * Custom error for Kafka producer operational issues.
 */
export class KafkaProducerError extends Error {
  constructor(message: string, public readonly code: string) {
    super(message);
    this.name = 'KafkaProducerError';
  }
}

/**
 * High-performance, idempotent Kafka producer.
 * Implements batching, retries with back-off, and graceful shutdown.
 */
export class KafkaEventProducer {
  private static instance: KafkaEventProducer;
  private readonly producer: Producer;
  private readonly metrics: MetricsManager;
  private readonly environment: string;

  private constructor(configProvider: KafkaConfigProvider, metrics: MetricsManager) {
    const config = configProvider.getConfig();
    this.metrics = metrics;
    this.environment = process.env.NODE_ENV || 'production';

    const kafka = new Kafka({
      clientId: config.clientId,
      brokers: config.brokers,
      sasl: config.sasl,
      ssl: config.ssl,
    });

    this.producer = kafka.producer({
      idempotent: config.producer.idempotent,
      maxInFlightRequests: config.producer.maxInFlightRequests,
      retry: {
        initialRetryTime: config.producer.retry.initialRetryTime,
        retries: config.producer.retry.retries,
      },
    });
  }

  /**
   * Initializes the producer singleton.
   */
  public static initialize(configProvider: KafkaConfigProvider, metrics: MetricsManager): KafkaEventProducer {
    if (!KafkaEventProducer.instance) {
      KafkaEventProducer.instance = new KafkaEventProducer(configProvider, metrics);
    }
    return KafkaEventProducer.instance;
  }

  /**
   * Connects to the Kafka broker.
   */
  public async connect(): Promise<void> {
    await this.producer.connect();
  }

  /**
   * Produces a transaction event to the specified topic.
   * Ensures the payload is wrapped in a signed MessageEnvelope.
   */
  public async produce<T extends Transaction>(topic: string, event: T): Promise<void> {
    const labels: MetricLabels = { environment: this.environment, stream: topic };

    await this.metrics.trackProducerOperation(labels, async () => {
      try {
        const envelope = await EventEnvelopeFactory.create(event);
        const record: ProducerRecord = {
          topic,
          messages: [{ value: JSON.stringify(envelope), key: event.transactionId }],
          compression: CompressionTypes.GZIP,
        };

        await this.producer.send(record);
      } catch (err) {
        this.handleError(topic, err);
        throw err;
      }
    });
  }

  /**
   * Handles errors, distinguishing between retriable and non-retriable cases.
   */
  private handleError(topic: string, error: unknown): void {
    const labels = { environment: this.environment, stream: topic, reason: error instanceof Error ? error.name : 'UnknownError' };

    // Increment failure counter in metrics
    MetricsManager.getInstance().recordProducerFailure(labels);
  }

  /**
   * Gracefully disconnects the producer, ensuring all pending messages are flushed.
   */
  public async gracefulShutdown(): Promise<void> {
    try {
      await this.producer.disconnect();
    } catch (err) {
      throw new KafkaProducerError('Failed to shutdown producer gracefully', 'SHUTDOWN_FAILED');
    }
  }

  /**
   * Sets up global process handlers for graceful shutdown.
   */
  public registerShutdownHandlers(): void {
    const shutdown = async () => {
      await this.gracefulShutdown();
      process.exit(0);
    };

    process.on('SIGTERM', shutdown);
    process.on('SIGINT', shutdown);
  }
}

import { z } from 'zod';
import { Registry } from 'prom-client';

/**
 * Zod schema for runtime validation of Kafka configuration.
 * Enforces production-grade security and tuning parameters.
 */
const KafkaConfigSchema = z.object({
  brokers: z.array(z.string()).min(1),
  clientId: z.string().min(1),
  groupId: z.string().min(1),
  sasl: z.object({
    mechanism: z.enum(['plain', 'scram-sha-256', 'scram-sha-512']),
    username: z.string().min(1),
    password: z.string().min(1),
  }).optional(),
  ssl: z.boolean().default(true),
  producer: z.object({
    idempotent: z.boolean().default(true),
    acks: z.union([z.literal('all'), z.literal(-1), z.literal(0), z.literal(1)]),
    maxInFlightRequests: z.number().int().min(1),
    batchSize: z.number().int().min(1024),
    lingerMs: z.number().int().min(0),
    retry: z.object({
      initialRetryTime: z.number().int(),
      retries: z.number().int(),
    }),
  }),
  consumer: z.object({
    sessionTimeout: z.number().int().min(6000),
    heartbeatInterval: z.number().int().min(2000),
    autoCommit: z.literal(false),
    maxBytesPerPartition: z.number().int().min(1048576),
  }),
});

export type KafkaConfig = z.infer<typeof KafkaConfigSchema>;

/**
 * KafkaConfigProvider manages loading, validating, and freezing
 * the Kafka configuration for the fraud detection pipeline.
 */
export class KafkaConfigProvider {
  private static instance: KafkaConfigProvider;
  private readonly config: KafkaConfig;
  private readonly metrics: Registry;

  private constructor(env: NodeJS.ProcessEnv, metrics: Registry) {
    this.metrics = metrics;

    const rawConfig = {
      brokers: (env.KAFKA_BROKERS || '').split(',').filter(Boolean),
      clientId: env.KAFKA_CLIENT_ID || 'fraud-detection-engine',
      groupId: env.KAFKA_GROUP_ID || 'fraud-detection-group',
      sasl: env.KAFKA_SASL_USERNAME
        ? {
            mechanism: (env.KAFKA_SASL_MECHANISM as any) || 'scram-sha-512',
            username: env.KAFKA_SASL_USERNAME,
            password: env.KAFKA_SASL_PASSWORD || '',
          }
        : undefined,
      ssl: env.NODE_ENV === 'production',
      producer: {
        idempotent: true,
        acks: 'all',
        maxInFlightRequests: 1,
        batchSize: 16384,
        lingerMs: 5,
        retry: {
          initialRetryTime: 300,
          retries: 8,
        },
      },
      consumer: {
        sessionTimeout: 10000,
        heartbeatInterval: 3000,
        autoCommit: false as const,
        maxBytesPerPartition: 1048576,
      },
    };

    const result = KafkaConfigSchema.safeParse(rawConfig);

    if (!result.success) {
      // Instrument validation failure
      this.metrics.getSingleMetric('config_validation_failure')?.set(1);
      throw new Error(`Kafka configuration validation failed: ${JSON.stringify(result.error.format())}`);
    }

    this.config = Object.freeze(result.data);
    this.metrics.getSingleMetric('config_validation_success')?.set(1);
  }

  /**
   * Initializes the KafkaConfigProvider with environment variables and registry.
   */
  public static initialize(env: NodeJS.ProcessEnv, metrics: Registry): KafkaConfigProvider {
    if (!KafkaConfigProvider.instance) {
      KafkaConfigProvider.instance = new KafkaConfigProvider(env, metrics);
    }
    return KafkaConfigProvider.instance;
  }

  /**
   * Retrieves the immutable configuration object.
   */
  public getConfig(): KafkaConfig {
    return this.config;
  }
}

import { Registry, Histogram, Counter } from 'prom-client';
import { z } from 'zod';

/**
 * Zod schema for metric labels to ensure consistency and prevent cardinality explosion.
 */
export const MetricLabelSchema = z.object({
  environment: z.string(),
  stream: z.string(),
  partition: z.string().optional(),
});

export type MetricLabels = z.infer<typeof MetricLabelSchema>;

/**
 * MetricsManager provides a high-precision observability layer for Kafka messaging operations.
 * It follows a singleton pattern to maintain registry consistency across the messaging client lifecycle.
 */
export class MetricsManager {
  private static instance: MetricsManager;
  private readonly registry: Registry;

  // Producer Metrics
  private readonly producerProduceDuration: Histogram<string>;
  private readonly producerEventsAttempted: Counter<string>;
  private readonly producerEventsSuccess: Counter<string>;
  private readonly producerEventsFailed: Counter<string>;

  // Consumer Metrics
  private readonly consumerProcessingDuration: Histogram<string>;
  private readonly consumerEventsConsumed: Counter<string>;
  private readonly consumerRebalanceCount: Counter<string>;
  private readonly consumerDlqIngressCount: Counter<string>;

  private constructor(registry: Registry) {
    this.registry = registry;

    // Define Producer Latency Histogram with P95/P99 tuned buckets (ms converted to seconds)
    this.producerProduceDuration = new Histogram({
      name: 'kafka_producer_produce_duration_seconds',
      help: 'Duration of message produce operations in seconds',
      registers: [this.registry],
      labelNames: ['environment', 'stream'],
      buckets: [0.001, 0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1.0],
    });

    this.producerEventsAttempted = new Counter({
      name: 'kafka_producer_events_attempted_total',
      help: 'Total events attempted to produce',
      registers: [this.registry],
      labelNames: ['environment', 'stream'],
    });

    this.producerEventsSuccess = new Counter({
      name: 'kafka_producer_events_success_total',
      help: 'Total successful produce operations',
      registers: [this.registry],
      labelNames: ['environment', 'stream'],
    });

    this.producerEventsFailed = new Counter({
      name: 'kafka_producer_events_failed_total',
      help: 'Total failed produce operations',
      registers: [this.registry],
      labelNames: ['environment', 'stream', 'reason'],
    });

    // Define Consumer Latency Histogram
    this.consumerProcessingDuration = new Histogram({
      name: 'kafka_consumer_processing_duration_seconds',
      help: 'End-to-end processing duration from poll to offset commit',
      registers: [this.registry],
      labelNames: ['environment', 'stream'],
      buckets: [0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1.0, 2.0],
    });

    this.consumerEventsConsumed = new Counter({
      name: 'kafka_consumer_events_consumed_total',
      help: 'Total events consumed',
      registers: [this.registry],
      labelNames: ['environment', 'stream'],
    });

    this.consumerRebalanceCount = new Counter({
      name: 'kafka_consumer_rebalance_total',
      help: 'Total number of consumer group rebalances',
      registers: [this.registry],
      labelNames: ['environment', 'stream'],
    });

    this.consumerDlqIngressCount = new Counter({
      name: 'kafka_consumer_dlq_ingress_total',
      help: 'Total events sent to Dead Letter Queue',
      registers: [this.registry],
      labelNames: ['environment', 'stream', 'reason'],
    });
  }

  public static initialize(registry: Registry): MetricsManager {
    if (!MetricsManager.instance) {
      MetricsManager.instance = new MetricsManager(registry);
    }
    return MetricsManager.instance;
  }

  public static getInstance(): MetricsManager {
    if (!MetricsManager.instance) {
      throw new Error('MetricsManager not initialized');
    }
    return MetricsManager.instance;
  }

  /**
   * Wraps an asynchronous Kafka producer operation with latency recording.
   */
  public async trackProducerOperation<T>(
    labels: MetricLabels,
    operation: () => Promise<T>
  ): Promise<T> {
    const validatedLabels = MetricLabelSchema.parse(labels);
    this.producerEventsAttempted.inc({ environment: validatedLabels.environment, stream: validatedLabels.stream });

    const start = process.hrtime.bigint();
    try {
      const result = await operation();
      const end = process.hrtime.bigint();

      this.producerProduceDuration.observe(
        { environment: validatedLabels.environment, stream: validatedLabels.stream },
        Number(end - start) / 1e9
      );
      this.producerEventsSuccess.inc({ environment: validatedLabels.environment, stream: validatedLabels.stream });
      return result;
    } catch (error) {
      this.producerEventsFailed.inc({ 
        environment: validatedLabels.environment, 
        stream: validatedLabels.stream,
        reason: error instanceof Error ? error.name : 'unknown'
      });
      throw error;
    }
  }

  /**
   * Records processing duration for a consumed event.
   */
  public recordConsumerLatency(labels: MetricLabels, startNs: bigint): void {
    const validatedLabels = MetricLabelSchema.parse(labels);
    const end = process.hrtime.bigint();
    this.consumerProcessingDuration.observe(
      { environment: validatedLabels.environment, stream: validatedLabels.stream },
      Number(end - startNs) / 1e9
    );
    this.consumerEventsConsumed.inc({ environment: validatedLabels.environment, stream: validatedLabels.stream });
  }

  /**
   * Tracks DLQ ingress.
   */
  public recordDlqIngress(labels: MetricLabels, reason: string): void {
    const validatedLabels = MetricLabelSchema.parse(labels);
    this.consumerDlqIngressCount.inc({
      environment: validatedLabels.environment,
      stream: validatedLabels.stream,
      reason,
    });
  }

  /**
   * Tracks consumer rebalances.
   */
  public recordRebalance(labels: MetricLabels): void {
    const validatedLabels = MetricLabelSchema.parse(labels);
    this.consumerRebalanceCount.inc({
      environment: validatedLabels.environment,
      stream: validatedLabels.stream,
    });
  }
}
